using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace Synkoz {
public sealed class MidiCasesR12:FlowLayoutPanel {
readonly FlowLayoutPanel cp=new FlowLayoutPanel(),np=new FlowLayoutPanel();readonly CheckBox condition=new CheckBox();readonly FlowLayoutPanel bounds=new FlowLayoutPanel();readonly MidiFilterR4 filter;readonly List<GraphEvent15> events;readonly bool live;readonly Action changed;bool filling;readonly List<CheckBox> channels=new List<CheckBox>(),kinds=new List<CheckBox>();readonly CheckedListBox ccs=new CheckedListBox{Width=165,Height=90,CheckOnClick=true},notes=new CheckedListBox{Width=165,Height=90,CheckOnClick=true};
public MidiCasesR12(MidiFilterR4 f,List<GraphEvent15> data,Action change,bool direct=false,bool help=true){filter=f;events=data;changed=change;live=direct||!help;AutoSize=true;AutoSizeMode=AutoSizeMode.GrowAndShrink;Width=350;MaximumSize=new Size(355,0);FlowDirection=FlowDirection.TopDown;WrapContents=false;
Controls.Add(new Label{Text="Aucune restriction cochée : toutes les informations disponibles",AutoSize=true,MaximumSize=new Size(345,0)});
var ch=new FlowLayoutPanel{Width=345,AutoSize=true,MaximumSize=new Size(345,0)};Controls.Add(ch);for(int i=1;i<=(f.ByTrack?16:32);i++){int value=i;var box=new CheckBox{Text=i.ToString(),AutoSize=true,MinimumSize=new Size(48,24),Checked=f.ByTrack?(f.Mask&(1<<(i-1)))!=0:f.ChannelsR9.Contains(i)};box.CheckedChanged+=delegate{if(filling)return;if(f.ByTrack){if(box.Checked)f.Mask|=1<<(value-1);else f.Mask&=~(1<<(value-1));}else{f.ChannelsR9.Remove(value);if(box.Checked)f.ChannelsR9.Add(value);}UpdateChoices();changed();};box.Tag=i;channels.Add(box);ch.Controls.Add(box);}
var types=new FlowLayoutPanel{Width=345,Height=50};Controls.Add(types);foreach(string kind in new[]{"Note","CC","Horloge","Start","Stop"}){string value=kind;var box=new CheckBox{Text=kind=="Note"?"Notes":kind,AutoSize=true,Checked=f.KindsR12.Contains(kind),Tag=kind};box.CheckedChanged+=delegate{if(filling)return;f.KindsR12.Remove(value);if(box.Checked)f.KindsR12.Add(value);UpdateChoices();changed();};kinds.Add(box);types.Controls.Add(box);}
var details=new FlowLayoutPanel{Width=345,Height=115};cp.Width=165;cp.Height=115;cp.Controls.Add(new Label{Text="Numéros CC (facultatif)",AutoSize=true});cp.Controls.Add(ccs);np.Width=165;np.Height=115;np.Controls.Add(new Label{Text="Notes (facultatif)",AutoSize=true});np.Controls.Add(notes);details.Controls.Add(cp);details.Controls.Add(np);Controls.Add(details);
ccs.ItemCheck+=delegate(object sender,ItemCheckEventArgs a){if(filling)return;int value=(int)ccs.Items[a.Index];f.CcsR12.Remove(value);if(a.NewValue==CheckState.Checked)f.CcsR12.Add(value);BeginInvoke((Action)(()=>{UpdateChoices();changed();}));};notes.ItemCheck+=delegate(object sender,ItemCheckEventArgs a){if(filling)return;int value=(int)notes.Items[a.Index];f.NotesR12.Remove(value);if(a.NewValue==CheckState.Checked)f.NotesR12.Add(value);BeginInvoke((Action)(()=>{UpdateChoices();changed();}));};
condition.Text="Filtrer les valeurs des CC sélectionnés";condition.AutoSize=true;condition.Checked=f.ConditionR12;Controls.Add(condition);bounds.Width=345;bounds.Height=30;var min=UiR2.Number(f.MinR12,0,127,2);var max=UiR2.Number(f.MaxR12,0,127,2);min.Width=max.Width=100;bounds.Controls.Add(min);bounds.Controls.Add(new Label{Text="et",AutoSize=true});bounds.Controls.Add(max);Controls.Add(bounds);condition.CheckedChanged+=delegate{f.ConditionR12=condition.Checked;bounds.Enabled=condition.Checked;changed();};min.ValueChanged+=delegate{f.MinR12=(double)min.Value;changed();};max.ValueChanged+=delegate{f.MaxR12=(double)max.Value;changed();};UpdateChoices();}
void UpdateChoices(){filling=true;try{foreach(var c in channels){int number=(int)c.Tag;c.Enabled=c.Checked||live||events.Any(e=>(filter.ByTrack?e.Track+1:MidiChannelR9.Number(e))==number&&MidiFilterLogicR12.Match(filter,e,false,true));}foreach(var k in kinds)k.Enabled=k.Checked||live||events.Any(e=>MidiFilterLogicR12.Kind(e)==(string)k.Tag&&MidiFilterLogicR12.Match(filter,e,true,false));ccs.Enabled=filter.KindsR12.Count==0||filter.KindsR12.Contains("CC");condition.Visible=ccs.Enabled;bounds.Visible=ccs.Enabled;bounds.Enabled=condition.Checked;notes.Enabled=filter.KindsR12.Count==0||filter.KindsR12.Contains("Note");cp.Visible=ccs.Enabled;np.Visible=notes.Enabled;Fill(ccs,events.Where(e=>e.Kind=="CC"&&Channel(e)).Select(e=>e.CC),filter.CcsR12);Fill(notes,events.Where(e=>e.Kind=="NoteOn"&&Channel(e)).Select(e=>e.Note),filter.NotesR12);}finally{filling=false;}}
bool Channel(GraphEvent15 e){return filter.ByTrack?filter.Mask==0||e.Track>=0&&e.Track<16&&(filter.Mask&(1<<e.Track))!=0:filter.ChannelsR9.Count==0||filter.ChannelsR9.Contains(MidiChannelR9.Number(e));}
void Fill(CheckedListBox box,IEnumerable<int> available,List<int> selected){var all=(live?Enumerable.Range(0,128):available).Concat(selected).Distinct().OrderBy(x=>x).ToArray();box.Items.Clear();foreach(int n in all)box.Items.Add(n,selected.Contains(n));}
}}
